'use strict';
const el=id=>document.getElementById(id);
const status=text=>{el('status').textContent=text};
function captureSelection(){const selection=window.getSelection();const selected=selection?.toString()||'';const anchor=selection?.anchorNode?.nodeType===1?selection.anchorNode:selection?.anchorNode?.parentElement;const focus=selection?.focusNode?.nodeType===1?selection.focusNode:selection?.focusNode?.parentElement;if(anchor?.closest?.('input,textarea,[contenteditable], [contenteditable] *')||focus?.closest?.('input,textarea,[contenteditable], [contenteditable] *'))return '';const node=document.activeElement;if(node&&(node.matches('input,textarea,[contenteditable], [contenteditable] *')||node.closest?.('[contenteditable]')))return '';return selected.slice(0,20001)}
el('capture').addEventListener('click',async()=>{status('');try{const [tab]=await chrome.tabs.query({active:true,currentWindow:true});if(!tab?.id||!/^https?:\/\//.test(tab.url||''))throw Error('Open a normal webpage first.');const results=await chrome.scripting.executeScript({target:{tabId:tab.id},func:captureSelection});const text=results?.[0]?.result||'';if(!text.trim())throw Error('Highlight non-sensitive webpage text first.');if(text.length>20000)throw Error('Selection exceeds 20,000 characters.');el('content').value=text;el('title').value=(tab.title||'Captured selection').slice(0,160);el('source').value=tab.url||'';status('Selection ready. Review it before saving.')}catch(e){status(e?.message||'Capture unavailable on this page.')}});
el('copy').addEventListener('click',async()=>{try{if(!el('content').value.trim())throw Error('Nothing to copy.');await navigator.clipboard.writeText(el('content').value);status('Text copied.')}catch(e){status(e?.message||'Copy unavailable.')}});
el('download').addEventListener('click',()=>{try{const title=el('title').value.trim();const body=el('content').value.trim();if(!title||!body)throw Error('Enter a title and content.');const data={title,body,sourceUrl:el('source').value,capturedAt:new Date().toISOString(),category:el('category').value,tags:el('tags').value.split(',').map(s=>s.trim()).filter(Boolean).slice(0,20)};const blob=new Blob([JSON.stringify(data,null,2)],{type:'application/json'});const url=URL.createObjectURL(blob);const link=document.createElement('a');link.href=url;link.download='keep-vault-capture.json';link.click();setTimeout(()=>URL.revokeObjectURL(url),1000);status('Capture saved as a local file. No data was uploaded.')}catch(e){status(e?.message||'Save failed.')}});
el('cancel').addEventListener('click',()=>{for(const id of ['title','content','source','tags'])el(id).value='';status('Capture cleared.')});


